<?php
function infra_ui_test($condition,$message){if(!$condition){fwrite(STDERR,'FAIL: '.$message.PHP_EOL);exit(1);}echo 'PASS: '.$message.PHP_EOL;}$root=dirname(__DIR__);$page=file_get_contents($root.'/superadmin_infraestructura.php');$helper=file_get_contents($root.'/inc/platform_health.php');$nav=file_get_contents($root.'/inc/nav.php');infra_ui_test(strpos($page,'tickex_is_super_admin')!==false,'infrastructure dashboard is restricted to superadministration');infra_ui_test(strpos($page,'sólo lectura')!==false&&strpos($page,'No instala, actualiza ni modifica')!==false,'dashboard clearly remains read only');infra_ui_test(strpos($helper,"extension_loaded('zip')")!==false,'ZIP startup problem is diagnosed');infra_ui_test(strpos($helper,"PRAGMA quick_check")!==false&&strpos($helper,"PRAGMA journal_mode")!==false,'SQLite integrity and concurrency are diagnosed');infra_ui_test(strpos($helper,'access_token')===false&&strpos($helper,'client_secret')===false,'diagnostic code never reads credential values');infra_ui_test(strpos($nav,'superadmin_infraestructura.php')!==false,'superadministrator navigation exposes infrastructure health');echo 'ALL PLATFORM HEALTH UI TESTS PASSED'.PHP_EOL;
